<template><div class="hero-grid grid min-h-screen place-items-center p-5"><div class="w-full max-w-md rounded-2xl border border-white/15 bg-[#160630]/90 p-8 text-white shadow-2xl"><BrandMark light/><h1 class="mt-8 text-3xl font-bold">Accès administration</h1><p class="mt-2 text-sm text-white/50">Session sécurisée par cookie httpOnly.</p><form class="mt-7 space-y-4" @submit.prevent="login"><label class="text-xs text-white/70">Email<input v-model="email" type="email" class="field mt-2 !border-white/15 !bg-white/5 !text-white" required/></label><label class="text-xs text-white/70">Mot de passe<input v-model="password" type="password" class="field mt-2 !border-white/15 !bg-white/5 !text-white" required/></label><p v-if="error" class="rounded-xl bg-red-500/10 p-3 text-sm text-red-200">{{ error }}</p><button class="btn-primary w-full" :disabled="pending">Se connecter</button></form></div></div></template>
<script setup lang="ts">definePageMeta({layout:false});useSeoMeta({title:'Administration',robots:'noindex,nofollow'});const email=ref(''),password=ref(''),error=ref(''),pending=ref(false);async function login(){pending.value=true;error.value='';try{await $fetch('/api/auth/login',{method:'POST',body:{email:email.value,password:password.value}});await navigateTo('/admin')}catch(e:any){error.value=e?.data?.statusMessage||'Connexion impossible'}finally{pending.value=false}}</script>
